import{Trie}from"./structs/trie.js";function sanitize(phrase){return phrase.trim().toLowerCase()}export class EmojiPrefixSearch{constructor(){this.tokenTrie=new Trie;this.wordToEmojisMap=new Map;this.emojiMap=new Map}setCollection(collection){this.clear();for(const record of collection){if(!record.base.string||!record.base.name){continue}const string=record.base.string;const name=record.base.name;const terms=this.tokenize(name).map((term=>sanitize(term)));terms.forEach((term=>{if(!this.wordToEmojisMap.has(term)){this.wordToEmojisMap.set(term,new Set)}this.wordToEmojisMap.get(term)?.add(string);this.emojiMap.set(string,record);this.tokenTrie.add(term)}))}}matchPrefixToEmojis(prefix){const results=new Set;const terms=this.tokenTrie.getKeys(prefix);for(const term of terms){const matchedItems=this.wordToEmojisMap.get(term);if(matchedItems!==undefined){matchedItems.forEach((item=>{results.add(item)}))}}return Array.from(results)}clear(){this.tokenTrie.clear();this.wordToEmojisMap.clear();this.emojiMap.clear()}tokenize(phrase){return phrase.split(" ").filter((token=>token.length>0))}getMatchedKeywords(emoji,term){if(!emoji.base.name){return[]}const PRIMARY_NAME_WEIGHT=1;return this.tokenize(sanitize(emoji.base.name)).map(((token,pos)=>({pos:pos,isMatched:token.startsWith(term),token:token,weight:PRIMARY_NAME_WEIGHT}))).filter((item=>item.isMatched))}scoreTermAgainstEmoji(emoji,term){let score=0;for(const item of this.getMatchedKeywords(emoji,term)){if(item.token.length===0){throw new Error("Token can not be empty.")}score+=item.weight/(1+item.pos)*(term.length/item.token.length)}return score}search(query){const queryScores=new Map;const sanitizedQuery=sanitize(query);this.tokenize(sanitizedQuery).forEach(((term,idx)=>{const termScores=new Map;const candidateEmojis=this.matchPrefixToEmojis(term);for(const emoji of candidateEmojis){const emojiRecord=this.emojiMap.get(emoji);if(emojiRecord){termScores.set(emoji,this.scoreTermAgainstEmoji(emojiRecord,term))}}for(const emoji of termScores.keys()){if(idx===0){const emojiName=this.emojiMap.get(emoji)?.base?.name??" ";queryScores.set(emoji,sanitizedQuery.length/emojiName.length)}if(queryScores.has(emoji)){queryScores.set(emoji,queryScores.get(emoji)*termScores.get(emoji))}}for(const emoji of queryScores.keys()){if(!termScores.has(emoji)){queryScores.delete(emoji)}}}));const results=Array.from(queryScores.keys()).map((emoji=>({item:this.emojiMap.get(emoji),score:queryScores.get(emoji)})));return this.sort(results)}sort(results){return results.sort(((emoji1,emoji2)=>emoji2.score-emoji1.score))}}